import pathlib,json,hashlib,importlib.util,collections,numpy as np,math
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
SRC=R/'y06_r3_bear_retest_research_v2.py'
sp=importlib.util.spec_from_file_location('r3',SRC);r3=importlib.util.module_from_spec(sp);sp.loader.exec_module(r3)
bt=r3.bt;H=bt.H;M=bt.M
P=R/'Y06_R6_DIRECTION_PROTOCOL_20261127.json';O=R/'Y06_R6_DIRECTION_RESULTS_20261127.json'
assert not P.exists() and not O.exists()
I=R/'Y06_R5_ENTRY_STAGE1_20261127.json'
p={'status':'RESEARCH_ONLY_NOT_PRODUCTION','parent_sha256':hashlib.sha256(I.read_bytes()).hexdigest(),'source_sha256':hashlib.sha256(SRC.read_bytes()).hexdigest(),'arms':['SHORT_DIRECT','LONG_DIRECT_DIAGNOSTIC','SHORT_AFTER_REBOUND','LONG_CONFIRMED_REBOUND','SHORT_AFTER_REBOUND_BEAR','LONG_CONFIRMED_REBOUND_BULL'],'definition':'Five R5 tapes unchanged. Direct LONG is a direction falsification only, not approved flip. After initial candidate, wait strictly subsequent 1-6 completed H1 candles; SHORT requires intervening confirmed rebound close >=0.5 entry ATR above its running low (strictly prior to signal), then bearish close below prior two H1 lows; LONG requires bullish close above prior two H1 highs and >0.5 ATR above running low, no short entry. Confirmed BTC+asset trailing24h same-direction condition for BEAR/BULL arms. No retrospective selection, no same-symbol overlap; no trade comparator equity 10000. 24h STOP8, 0.30 gross, two slots, 12h cooldown, 10/30bps; no funding. All periods already inspected.','control':'same-symbol +/-1,3,6,9,12,18,24h matched BTC and asset 24h sign, QA, same exit and wallet, 32 fixed draws for each arm on each period with >=2 alternatives; seed 2026112707. No independent trials.'}
P.write_text(json.dumps(p,indent=2),encoding='utf8')
raw=json.loads(I.read_text(encoding='utf8'))['candidate_intentions'];btc,_=bt.data('BTC','1h');hs={};ms={};qa={}
for sym in bt.SYMS[1:]:
 h,_=bt.data(sym,'1h');m,_=bt.data(sym,'5m');hs[sym]=h;ms[sym]=m;qa[sym]=r3.prepare_qa(h,m)[0];print('LOAD',sym,flush=True)
def endof(per):return bt.PERIODS[per][1] if per!='FORWARD_INSPECTED' else bt.T('2026-11-26T00:00:00Z')
def signs(sym,t):
 h=hs[sym];i=(t-bt.HS)//H
 if i<25 or i>=len(h) or not np.isfinite(h[i-25:i,3]).all() or not np.isfinite(btc[i-25:i,3]).all():return None
 return (bool(btc[i-1,3]>=btc[i-25,3]),bool(h[i-1,3]>=h[i-25,3]))
def trade(x,direction):
 if direction=='SHORT':
  z=r3.calc_trade(x,ms[x['symbol']],'STOP8_TIME24')
  return z if z and z['exitTs']<endof(x['period']) else None
 m=ms[x['symbol']];k=(x['entryTs']-bt.MS)//M;j=k+288
 if k<0 or j>=len(m) or not np.isfinite(m[k:j+1,:4]).all():return None
 ep=float(m[k,0]);stop=ep*.92;xp=float(m[j,0]);et=bt.MS+j*M;reason='TIME24'
 hit=np.flatnonzero(m[k:j,2]<=stop)
 if len(hit):
  q=k+int(hit[0]);xp=float(min(m[q,0],stop));et=bt.MS+(q+1)*M;reason='HARD_STOP8'
 if et>=endof(x['period']):return None
 return {**x,'exitTs':et,'entry':ep,'exitPrice':xp,'direction':'LONG','rawReturn':xp/ep-1,'exitReason':reason,'mode':'STOP8_TIME24'}
def confirmations(x):
 sym=x['symbol'];h=hs[sym];i=(x['entryTs']-bt.HS)//H;a=x['breakAtr'];lo=h[i-1,2];rebound=False;ss=None;ll=None
 for j in range(i+1,min(i+7,len(h))):
  t=bt.HS+j*H
  if t>=bt.PERIODS[x['period']][1] or not qa[sym][j] or not np.isfinite(h[j-3:j,:4]).all():break
  c=h[j-1];prior=h[j-3:j-1]
  if ss is None and rebound and c[3]<c[0] and c[3]<prior[:,2].min():ss={**x,'entryTs':t,'originTs':x['entryTs']}
  if ll is None and c[3]>c[0] and c[3]>prior[:,1].max() and c[3]>=lo+.5*a:ll={**x,'entryTs':t,'originTs':x['entryTs']}
  lo=min(lo,c[2])
  if c[3]>=lo+.5*a:rebound=True
 return ss,ll
def compact(w):return {k:v for k,v in w.items() if k!='accepted'}
def dedup(cs):
 return list({(x['symbol'],x['entryTs']):x for x in cs}.values())
tapes={}
for family,cs in raw.items():
 tape={k:[] for k in p['arms']}
 tape['SHORT_DIRECT']=cs;tape['LONG_DIRECT_DIAGNOSTIC']=cs
 for x in cs:
  ss,ll=confirmations(x)
  if ss:
   tape['SHORT_AFTER_REBOUND'].append(ss)
   if signs(ss['symbol'],ss['entryTs'])==(False,False):tape['SHORT_AFTER_REBOUND_BEAR'].append(ss)
  if ll:
   tape['LONG_CONFIRMED_REBOUND'].append(ll)
   if signs(ll['symbol'],ll['entryTs'])==(True,True):tape['LONG_CONFIRMED_REBOUND_BULL'].append(ll)
 tapes[family]={k:dedup(v) for k,v in tape.items()}
out={};fulltrades={}
for family,tape in tapes.items():
 out[family]={};fulltrades[family]={}
 for arm,cs in tape.items():
  direction='LONG' if arm.startswith('LONG') else 'SHORT'
  ts=[z for x in cs if (z:=trade(x,direction)) is not None];fulltrades[family][arm]=ts;out[family][arm]={}
  for per in bt.PERIODS:
   rr=[x for x in ts if x['period']==per]
   w={str(f):compact(bt.wallet(rr,per,f,ms)) for f in (10,30)}
   out[family][arm][per]={'candidates':sum(x['period']==per for x in cs),'valid':len(rr),'wallet':w,'mean_trade_net_pct':float(np.mean([100*(x['rawReturn']-.003) for x in rr])) if rr else None}
  v=[out[family][arm][per]['wallet']['30'] for per in bt.PERIODS]
  print('BT',family,arm,[(round(q['terminal_jpy']),round(q['max_dd_pct'],2),q['n'],round(q['win_pct'],2) if q['win_pct'] is not None else None) for q in v],flush=True)
# Save all fixed arms before matching. Controls on all arms with positive 30bps all periods, plus direct diagnostic arms (predeclared).
S=R/'Y06_R6_DIRECTION_STAGE1_20261127.json';assert not S.exists();S.write_text(json.dumps({'protocol':p,'results':out},indent=2,allow_nan=False),encoding='utf8')
rng=np.random.default_rng(2026112707)
for family,arms in out.items():
 for arm,rr in arms.items():
  if not (arm in ('SHORT_DIRECT','LONG_DIRECT_DIAGNOSTIC') or all(rr[per]['wallet']['30']['terminal_jpy']>10000 for per in bt.PERIODS)):continue
  direction='LONG' if arm.startswith('LONG') else 'SHORT'
  for per,(beg,end) in bt.PERIODS.items():
   pairs=[]
   for x in fulltrades[family][arm]:
    if x['period']!=per:continue
    sym=x['symbol'];state=signs(sym,x['entryTs']);alts=[]
    for off in (-24,-18,-12,-9,-6,-3,-1,1,3,6,9,12,18,24):
     t=x['entryTs']+off*H;j=(t-bt.HS)//H
     if not(beg<=t<end and 220<=j<len(hs[sym]) and qa[sym][j] and signs(sym,t)==state):continue
     z=trade({**x,'entryTs':t},direction)
     if z is not None:alts.append(z)
    if len(alts)>=2:pairs.append((x,alts))
   actual=compact(bt.wallet([x for x,a in pairs],per,30,ms))
   ds=[compact(bt.wallet([a[rng.integers(len(a))] for x,a in pairs],per,30,ms)) for _ in range(32)]
   vals=[d['terminal_jpy'] for d in ds]
   delta=float(np.mean([100*(x['rawReturn']-np.mean([z['rawReturn'] for z in a])) for x,a in pairs])) if pairs else None
   rr[per]['matched']={'n_pairs':len(pairs),'actual':actual,'mean_terminal':float(np.mean(vals)),'mean_dd':float(np.mean([d['max_dd_pct'] for d in ds])),'beats':sum(actual['terminal_jpy']>v for v in vals),'per_trade_delta_pp':delta,'draws':ds}
   print('MATCH',family,arm,per,len(pairs),round(actual['terminal_jpy']),round(np.mean(vals)),rr[per]['matched']['beats'],delta,flush=True)
O.write_text(json.dumps({'protocol':p,'stage1_sha256':hashlib.sha256(S.read_bytes()).hexdigest(),'results':out},indent=2,allow_nan=False),encoding='utf8')
print('SAVED',hashlib.sha256(O.read_bytes()).hexdigest(),flush=True)
